class Solution {
    public boolean isPrefixString(String s,String[] words){
        StringBuilder builder=new StringBuilder();
        for(String word:words){
            builder.append(word);
            if(builder.length()>=s.length())return builder.toString().equals(s);
        }
        return false;
    }
}

code.kotlin:
class Solution {
    fun isPrefixString(s:String,words:Array<String>):Boolean{
        val builder=StringBuilder();
        for(word in words){
            builder.append(word);
            if(builder.length>=s.length)return builder.toString()==s
        };
        return false
    }
}

code.cpp:
class Solution {
    public: bool isPrefixString(string s,vector<string>& words){
        string value;
        for(string& word:words){
            value+=word;
            if(value.size()>=s.size())return value==s;
        }
        return false;
    }
};
